llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C32"],
      "claim": "Selegiline absolute oral bioavailability was 4% in healthy volunteers after a 10 mg oral dose compared with IV, well below the 20% threshold; multiple selegiline records consistently report 4–10%."
    },
    {
      "card_ids": ["C05"],
      "claim": "Brexanolone is reported to have <5% oral bioavailability in humans when given orally versus intravenous infusion, directly supporting a low F classification."
    },
    {
      "card_ids": ["C13"],
      "claim": "Amitriptyline has a weighted-mean oral bioavailability of 45% in humans, above the 20% threshold, but this positive evidence has lower assay-transfer applicability than the high-transfer low-bioavailability evidence."
    }
  ],
  "confidence": "moderate",
  "contradictory_card_ids": ["C13"],
  "decision_summary": "High-transfer evidence from selegiline, brexanolone, N-0437, and rotigotine consistently indicates low oral bioavailability (<20%), while lower-transfer positive values from amitriptyline, alfentanil, and amiodarone are less applicable. Prediction: low.",
  "evidence_gaps": [
    "The highest-transfer record (C33) reports a 5–40% range that straddles the 20% threshold, so it is uninformative for the F≥20% classification.",
    "Alfentanil has a conflicting 1% absolute bioavailability record (C36) alongside 37–51% values; ordinary-condition studies were used, but the conflict adds uncertainty."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C32", "C05"],
  "revision_action": "initial",
  "supportive_card_ids": ["C32", "C05"]
}

